"""Generate experiment agents or a Claude Code plugin from the shared source.

Requires Python 3.11+. Run with --output <project> and optionally --agent,
--check (read-only comparison), or --force (replace generated files).
Use --agent claude-plugin --output plugins/experiments to build the plugin.
See docs/agent-plugins.md for marketplace distribution and maintenance.
"""

import argparse
import json
from pathlib import Path
import re
import sys
import tomllib

SOURCE = Path(__file__).resolve().parents[1]


def quote(text):
    return json.dumps(text, ensure_ascii=False)


def render(source, agent):
    """Return relative output paths and standalone definitions without writing."""
    registry = tomllib.loads((source / "registry.toml").read_text(encoding="utf-8"))
    common = (source / "common.md").read_text(encoding="utf-8").strip()
    records = (source.parents[1] / "skills/setup-experiments/references/records.md").read_text(
        encoding="utf-8"
    ).strip()
    outputs = {}
    names = set()
    declarations = []
    for role in registry["agents"]:
        name = role["name"]
        if not re.fullmatch(r"[a-z][a-z0-9-]*", name) or name in names:
            raise ValueError(f"Invalid or duplicate agent name: {name}")
        names.add(name)
        instructions = (source / "roles" / f"{name}.md").read_text(encoding="utf-8").strip()
        body = f"{common}\n\n{records}\n\n{instructions}\n"
        if agent in ("all", "claude-code", "claude-plugin"):
            directory = "agents" if agent == "claude-plugin" else ".claude/agents"
            outputs[Path(f"{directory}/{name}.md")] = (
                f"---\nname: {quote(name)}\ndescription: {quote(role['description'])}\n"
                "model: inherit\n---\n\n"
                "<!-- Generated by agents/experiments/scripts/register.py. Edit the shared source. -->\n\n"
                + body
            )
        if agent in ("all", "codex"):
            declarations.append(
                f"[agents.{name}]\ndescription = {quote(role['description'])}\n"
                f'config_file = "agents/{name}.toml"\n'
            )
            outputs[Path(f".codex/agents/{name}.toml")] = (
                "# Generated by agents/experiments/scripts/register.py. Edit the shared source.\n"
                f"name = {quote(name)}\ndescription = {quote(role['description'])}\n"
                f"developer_instructions = {quote(body)}\n"
            )
    if declarations:
        outputs[Path(".codex/experiment-agents.toml")] = (
            "# Generated registration fragment. Merge these tables into .codex/config.toml.\n\n"
            + "\n".join(declarations)
        )
    if agent == "claude-plugin":
        root = source.parents[1]
        manifest = json.loads(
            (root / "plugins/experiments/.claude-plugin/plugin.json").read_text(encoding="utf-8")
        )
        workflow = (source / "workflow.md").read_text(encoding="utf-8")
        for name in names | {"setup-experiments"}:
            workflow = workflow.replace(f"`{name}`", f"`{manifest['name']}:{name}`")
        setup = root / "skills/setup-experiments"
        outputs[Path("skills/setup-experiments/SKILL.md")] = (setup / "SKILL.md").read_text(
            encoding="utf-8"
        )
        outputs[Path("skills/setup-experiments/references/records.md")] = records + "\n"
        entry = (source / "run-experiments.md").read_text(encoding="utf-8")
        entry = entry.replace("(workflow.md)", "(references/workflow.md)")
        entry = entry.replace(
            "(../../skills/setup-experiments/references/records.md)", "(references/records.md)"
        )
        outputs[Path("skills/run-experiments/SKILL.md")] = entry
        outputs[Path("skills/run-experiments/references/workflow.md")] = workflow
        outputs[Path("skills/run-experiments/references/records.md")] = records + "\n"
        outputs[Path("LICENSE")] = (root / "LICENSE").read_text(encoding="utf-8")
    return outputs


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True, help="Target project directory")
    parser.add_argument(
        "--agent", choices=("all", "claude-code", "codex", "claude-plugin"), default="all"
    )
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="Report missing/stale definitions without writing")
    mode.add_argument("--force", action="store_true", help="Replace differing generated files")
    args = parser.parse_args(argv)
    try:
        outputs = render(SOURCE, args.agent)
        target = args.output.resolve()
        changed = []
        conflicts = []
        for relative, content in outputs.items():
            path = target / relative
            if path.exists():
                if path.read_text(encoding="utf-8") == content:
                    continue
                conflicts.append(relative)
            changed.append(relative)
        if args.check:
            for relative in changed:
                print(f"Missing or stale: {relative}")
            return 1 if changed else 0
        if conflicts and not args.force:
            print("Existing files differ; inspect them before updating with --force:", file=sys.stderr)
            for relative in conflicts:
                print(relative, file=sys.stderr)
            return 1
        for relative in changed:
            path = target / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(outputs[relative], encoding="utf-8", newline="\n")
            print(f"Written: {path}")
        print(f"Ready: {len(outputs)} files ({len(changed)} written)")
        return 0
    except (OSError, ValueError, KeyError) as error:
        print(f"Registration failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
